import { ref, computed } from 'vue';
import type { Ref } from 'vue';

export function useCrossPageSelection<T>(idOf: (item: T) => string, cap?: number) {
  const map = ref(new Map<string, T>()) as Ref<Map<string, T>>;
  const selectedItems = computed(() => [...map.value.values()]);
  const count = computed(() => map.value.size);
  const remainingCapacity = computed(() => (cap === undefined ? Infinity : Math.max(0, cap - map.value.size)));
  const isSelected = (id: string) => map.value.has(id);
  function toggle(item: T) {
    const key = idOf(item);
    const next = new Map(map.value);
    if (next.has(key)) next.delete(key);
    else if (remainingCapacity.value > 0) next.set(key, item);
    map.value = next;
  }
  function togglePage(items: T[]) {
    const next = new Map(map.value);
    const allSelected = items.length > 0 && items.every((i) => next.has(idOf(i)));
    if (allSelected) items.forEach((i) => next.delete(idOf(i)));
    else
      for (const i of items) {
        if (cap !== undefined && next.size >= cap) break;
        next.set(idOf(i), i);
      }
    map.value = next;
  }
  function pageSelectAllState(items: T[]): boolean | 'indeterminate' {
    if (items.length === 0) return false;
    const n = items.filter((i) => map.value.has(idOf(i))).length;
    return n === 0 ? false : n === items.length ? true : 'indeterminate';
  }
  function clear() {
    map.value = new Map();
  }
  return { selectedItems, count, remainingCapacity, isSelected, toggle, togglePage, pageSelectAllState, clear };
}
