export function useSelectorItems(
  key: string[],
  fetcher: () => Promise<{ items: string[] }>,
  hasInitialValue: () => boolean
) {
  const opened = ref(false);
  const enabled = computed(() => hasInitialValue() || opened.value);
  const { data, error, isLoading } = useQuery({ key: () => key, query: fetcher, enabled });
  const items = computed<SelectItem[]>(() => (data.value?.items ?? []).map((value) => ({ name: value, value })));
  const onOpenChange = (isOpen: boolean) => {
    if (isOpen) opened.value = true;
  };
  return { items, error, loading: isLoading, onOpenChange };
}
