<template>
  <Dialog v-model:open="model" @update:open="onOpenUpdate">
    <DialogContent class="rounded-lg max-w-md gap-6">
      <DialogHeader class="gap-y-2 text-left">
        <DialogTitle class="text-xl">Send batch outreach</DialogTitle>
        <Alert class="my-2">
          <InfoIcon />
          <AlertTitle>Personalized Messages</AlertTitle>
          <AlertDescription>
            Each contact will receive a personalized message by email or SMS, depending on the channel setting and what
            the contact is reachable by. Context will include name and other personal info, past projects the canvasser
            worked on, and history of previous interactions.
          </AlertDescription>
        </Alert>
        <Alert v-if="skippedByEmail.size > 0" variant="warning" class="my-2">
          <TriangleAlertIcon />
          <AlertTitle>Some contacts were skipped</AlertTitle>
          <AlertDescription>
            {{ skippedByEmail.size }} of {{ displayContacts.length }} contacts were skipped and did not receive a
            message.
          </AlertDescription>
        </Alert>
        <DialogDescription class="font-normal text-base text-accent-foreground">
          {{
            skippedByEmail.size > 0
              ? `Send results for ${displayContacts.length} contact(s):`
              : `You are about to send messages to ${displayContacts.length} contact(s):`
          }}
        </DialogDescription>
      </DialogHeader>

      <div class="max-h-60 overflow-y-auto border rounded-md divide-y">
        <div v-for="contact in displayContacts" :key="contact.email" class="flex flex-col px-3 py-2">
          <span class="text-sm font-medium">
            {{ formatContactName(contact.first_name, contact.last_name) }}
          </span>
          <span class="text-xs text-muted-foreground">{{ contact.email }}</span>
          <Badge v-if="skippedByEmail.has(contact.email)" variant="warning" size="sm" class="mt-1 self-start">
            Skipped - {{ getSkippedContactReason(skippedByEmail.get(contact.email)!).label }}
          </Badge>
        </div>
      </div>

      <div v-if="showsIgnoreQuietHours" class="flex items-center justify-between gap-4">
        <div class="flex flex-col">
          <Label for="ignore-quiet-hours" class="text-sm font-medium">Ignore quiet hours</Label>
          <span class="text-xs text-muted-foreground">
            Applies to email only. Email waits for the recipient's local daytime unless you turn this on to send right
            away.
          </span>
        </div>
        <Switch id="ignore-quiet-hours" v-model="ignoreQuietHours" />
      </div>

      <div v-if="isAdmin && sentSnapshot.length === 0" class="flex flex-col gap-1.5">
        <Label for="channel_strategy" class="text-sm font-medium">Channel</Label>
        <span class="text-xs text-muted-foreground">
          {{ channelStrategyDescription }}
        </span>
        <FormField
          v-slot="{ componentField }"
          name="channel_strategy"
          :validate-on-blur="false"
          :validate-on-model-update="false"
        >
          <KitFormsSelect :component-field="componentField" :items="channelStrategyOptions" />
        </FormField>
      </div>

      <p v-if="showsSmsWindowNotice" class="text-xs text-muted-foreground">
        SMS can only be sent 8 AM-9 PM in each recipient's local time (US law). Anyone outside that window now is queued
        and texted when it opens.
      </p>

      <DialogFooter>
        <div class="flex flex-wrap justify-end gap-2">
          <DialogClose as-child>
            <Button variant="outline" class="h-10 px-4">{{ sentSnapshot.length > 0 ? 'Close' : 'Cancel' }}</Button>
          </DialogClose>
          <Button v-if="sentSnapshot.length === 0" class="h-10 px-4" :loading="isLoading" @click="onConfirm">
            Send
          </Button>
        </div>
      </DialogFooter>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import { useForm } from 'vee-validate';
import type { RecruitmentChannelStrategy, RecruitmentMessageSendBatchResponse, SkippedContactReason } from '~/client';
import { useRecruitmentMessageSendBatch } from '~/mutations/recruitment/messages/sendBatch';
import { useProjectSendBatch } from '~/mutations/recruitment/projectSendBatch';
import { getSkippedContactReason } from '~/constants/recruitment/skippedContactReasonConfig';
import { channelStrategyOptions } from '~/constants/recruitment/channelStrategyConfig';
import { DialogContent } from '~/components/ui/dialog';
import { FormField } from '~/components/ui/form';
import { AlertDescription, AlertTitle } from '~/components/ui/alert';
import { InfoIcon, TriangleAlertIcon } from 'lucide-vue-next';

export interface SelectableContact {
  email: string;
  first_name: string | null;
  last_name: string | null;
}

const props = defineProps<{
  mode: 'general' | 'project';
  selectedContacts: SelectableContact[];
  projectId?: string;
  defaultChannelStrategy: RecruitmentChannelStrategy;
  defaultStrategySource: 'campaign' | 'general_settings';
}>();

const emit = defineEmits<{
  (e: 'sent'): void;
}>();

const model = defineModel<boolean>({ default: false });

const { sendBatch, isSendBatchLoading } = useRecruitmentMessageSendBatch();
const { projectSendBatch, isProjectSendBatchLoading } = useProjectSendBatch();
const { isAdmin } = useUserRole();

const isLoading = computed(() => isSendBatchLoading.value || isProjectSendBatchLoading.value);

const skippedByEmail = ref<Map<string, SkippedContactReason>>(new Map());
const sentSnapshot = ref<SelectableContact[]>([]);
const ignoreQuietHours = ref(false);
// One idempotency key per send action, minted for the exact payload being sent: a retry after an error keeps
// the key, so the server returns the original result instead of sending twice. Editing anything after a
// failure - the channel, the quiet-hours override, the selection - makes it a new action and mints a new key;
// a reused key would make the server answer with the ORIGINAL batch and silently ignore the edit. Cleared on
// close so reopening the dialog begins a fresh action.
const idempotencyKey = ref('');
const keyedPayload = ref('');

// Prefill the selector with the effective default so onConfirm can omit channel_strategy while it still
// equals that default (the backend then re-resolves it at send time) and send an explicit value only when
// the admin changed it. KitFormsSelect needs a genuine vee-validate componentField - a hand-built object
// with inert handlers silently breaks its internal binding.
const { values, resetForm } = useForm<{ channel_strategy: RecruitmentChannelStrategy }>({
  initialValues: { channel_strategy: props.defaultChannelStrategy },
});

// emit('sent') clears the parent selection, so once a send returns we render the frozen
// snapshot instead of props to keep the skip annotations on screen.
const displayContacts = computed(() => (sentSnapshot.value.length > 0 ? sentSnapshot.value : props.selectedContacts));

const channelStrategyDescription = computed(() =>
  props.defaultStrategySource === 'campaign'
    ? "Prefilled from the campaign's channel. Change it to send this batch on a different channel."
    : 'Prefilled from your general recruitment settings. Change it to send this batch on a different channel.'
);

// The quiet-hours override applies to email only; an SMS-only batch sends no email, so hide the control
// entirely rather than show a toggle that does nothing.
const showsIgnoreQuietHours = computed(
  () => isAdmin.value && sentSnapshot.value.length === 0 && values.channel_strategy !== 'sms_only'
);

const showsSmsWindowNotice = computed(
  () => sentSnapshot.value.length === 0 && values.channel_strategy !== 'email_only'
);

// also called at the programmatic close below - reka doesn't emit update:open for controlled writes
function onOpenUpdate(open: boolean) {
  if (!open) {
    skippedByEmail.value = new Map();
    sentSnapshot.value = [];
    ignoreQuietHours.value = false;
    idempotencyKey.value = '';
    keyedPayload.value = '';
    resetForm();
  }
}

async function onConfirm() {
  const contacts = [...props.selectedContacts];
  const body = {
    emails: contacts.map((c) => c.email),
    ignore_quiet_hours: ignoreQuietHours.value,
    channel_strategy: values.channel_strategy === props.defaultChannelStrategy ? undefined : values.channel_strategy,
  };
  const payloadFingerprint = JSON.stringify(body);
  if (!idempotencyKey.value || keyedPayload.value !== payloadFingerprint) {
    idempotencyKey.value = crypto.randomUUID();
    keyedPayload.value = payloadFingerprint;
  }
  let response: RecruitmentMessageSendBatchResponse | null;
  if (props.mode === 'project') {
    response = await projectSendBatch({
      projectId: props.projectId!,
      body: { ...body, idempotency_key: idempotencyKey.value },
    }).catch(() => null);
  } else {
    response = await sendBatch({ ...body, idempotency_key: idempotencyKey.value }).catch(() => null);
  }
  if (!response) return;

  skippedByEmail.value = new Map(response.skipped.map((s): [string, SkippedContactReason] => [s.email, s.reason]));
  sentSnapshot.value = contacts;
  const skippedCount = response.skipped.length;

  if (response.created_count > 0) {
    emit('sent');
  }

  const noun = response.created_count === 1 ? 'message' : 'messages';
  const { allSkipped } = showSendBatchResultToast(
    { createdCount: response.created_count, skippedCount },
    {
      allSent: { title: `${response.created_count} ${noun} sent successfully` },
      partial: {
        title: `Sent ${response.created_count}, skipped ${skippedCount}`,
        description: 'See the contact list for skip reasons.',
      },
      allSkipped: {
        title: 'No messages sent',
        description: `All ${skippedCount} contacts were skipped. See the contact list for skip reasons.`,
      },
    }
  );

  if (!allSkipped && skippedCount === 0) {
    model.value = false;
    onOpenUpdate(false);
  }
}
</script>
