// Compare the tracked-filter projection by value across a nav: page-only nav keeps every tracked
// filter (AppPagination does {...route.query, page}) -> keep selection; any filter change -> clear.
// prev undefined -> never clear (no prior projection to diff against).
export function shouldClearSelectionOnNav<T>(next: readonly T[], prev: readonly T[] | undefined): boolean {
  if (!prev) return false;
  return JSON.stringify(next) !== JSON.stringify(prev);
}
