export function exhaustionLabel(contact: {
  is_general_exhausted: boolean;
  is_project_exhausted: boolean;
}): string | null {
  if (contact.is_general_exhausted && contact.is_project_exhausted) return 'Exhausted (Both)';
  if (contact.is_general_exhausted) return 'Exhausted (General)';
  if (contact.is_project_exhausted) return 'Exhausted (Project)';
  return null;
}
