import {
  sendBatchProjectScopedRecruitmentMessages,
  type ProjectRecruitmentSendBatchRequest,
  type RecruitmentMessageSendBatchResponse,
} from '~/client';

export interface ProjectSendBatchArgs {
  projectId: string;
  body: ProjectRecruitmentSendBatchRequest;
}

export const useProjectSendBatch = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (args: ProjectSendBatchArgs): Promise<RecruitmentMessageSendBatchResponse> =>
      sendBatchProjectScopedRecruitmentMessages({
        composable: '$fetch',
        path: { project_id: args.projectId },
        // narrow the optional channel_strategy's null -> undefined (null = use the configured strategy).
        body: { ...args.body, channel_strategy: args.body.channel_strategy ?? undefined },
      }),
    onSuccess: (_data, vars) => {
      queryCache.invalidateQueries({ key: ['recruitment-messages.list'] });
      queryCache.invalidateQueries({ key: ['recruitment.messages.activity.by_project_id', vars.projectId] });
    },
    onError: (error) => {
      showToastError(error);
    },
  });

  return {
    projectSendBatch: mutateAsync,
    isProjectSendBatchLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
